//! Minimal re-implementation of the `tsl::hopscotch_map` interface used by
//! the test program. Behaviorally it is an insertion-agnostic hash map:
//! `insert` adds a key/value pair (keeping the existing value on duplicate
//! keys, like `std::map::insert` / `tsl::hopscotch_map::insert`), and `size`
//! reports the number of stored entries.

use std::collections::HashMap;
use std::hash::Hash;

/// Drop-in equivalent of `tsl::hopscotch_map<K, V>` for the operations
/// exercised by the program (`new`, `insert`, `size`).
pub struct HopscotchMap<K, V> {
    inner: HashMap<K, V>,
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn new() -> Self {
        HopscotchMap {
            inner: HashMap::new(),
        }
    }

    /// Mirrors `hopscotch_map::insert({key, value})`: on a duplicate key the
    /// already-stored value is kept and the map is left unchanged.
    pub fn insert(&mut self, key: K, value: V) {
        self.inner.entry(key).or_insert(value);
    }

    pub fn size(&self) -> usize {
        self.inner.len()
    }
}

