mod hopscotch_map;

use hopscotch_map::HopscotchMap;

/// Equivalent of C++ `std::stoi` for the inputs this program can receive:
/// skips leading whitespace, accepts an optional sign, then parses the
/// leading run of decimal digits (trailing garbage is ignored, as `stoi`
/// does). Panics on invalid input, mirroring `std::invalid_argument`.
fn stoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && (bytes[i] as char).is_whitespace() {
        i += 1;
    }
    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }
    let start = i;
    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value * 10 + (bytes[i] - b'0') as i64;
        i += 1;
    }
    if i == start {
        panic!("stoi: no conversion could be performed");
    }
    if negative {
        value = -value;
    }
    value as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut count: i32 = 1;
    if args.len() > 1 && args[1] == "--a" {
        count = stoi(&args[2]);
    }

    let mut map: HopscotchMap<i32, String> = HopscotchMap::new();
    for i in 0..count {
        map.insert(i, format!("value{}", i));
    }

    println!("{}", map.size());
}

